// Small embedded broadcaster marks. No external logo requests at runtime.
const logos: Record<string,string> = {
  supersport: 'data:image/png;base64,',
  skysports: 'data:image/png;base64,',
  espn: 'data:image/svg+xml;base64,',
  dazn: 'data:image/svg+xml;base64,',
  tnt: 'data:image/svg+xml;base64,',
  bein: 'data:image/svg+xml;base64,',
  motogp: 'data:image/svg+xml;base64,',
  bbc: 'data:image/svg+xml;base64,',
  canal: 'data:image/svg+xml;base64,',
  cnn: 'data:image/svg+xml;base64,',
  foxnews: 'data:image/svg+xml;base64,',
  foxsports: 'data:image/svg+xml;base64,',
  ziggo: 'data:image/svg+xml;base64,',
  tsn: 'data:image/png;base64,',
  nbcsports: 'data:image/png;base64,',
  sonysports: 'data:image/png;base64,',
};
/** Only match broadcaster names in the channel title, never provider labels. */
export function channelLogo(title:string): string | null {
  const patterns: Array<[RegExp,string]> = [
    [/\bs(?:u|\*)per\s*sport\b/i, 'supersport'],
    [/\bsky\s+sports?\b/i, 'skysports'],
    [/\bespn(?:\d+|news|u)?\b/i, 'espn'], [/\bdazn\b/i, 'dazn'],
    [/\btnt\s+sports?\b/i, 'tnt'], [/\bbein\s*sports?\b/i, 'bein'],
    [/\bfox\s+news\b/i, 'foxnews'], [/\bfox\s+(?:sports?|deportes)\b/i, 'foxsports'],
    [/\bbbc\b/i, 'bbc'], [/\bcnn\b/i, 'cnn'], [/\bcanal\s*(?:\+|plus\b)/i, 'canal'],
    [/\btsn\s*\d*\b/i, 'tsn'], [/\bnbc\s+sports?\b/i, 'nbcsports'], [/\bsony\s+sports?\b/i, 'sonysports'],
    [/\bziggo\s*sport\b/i, 'ziggo'], [/\bmoto\s*gp\b/i, 'motogp'],
  ];
  return logos[patterns.find(([pattern])=>pattern.test(title))?.[1] || ''] || null;
}
